import{_ as i,o as a,c as t,a2 as e}from"./chunks/framework.Cd7uensT.js";const u=JSON.parse('{"title":"版本更新","description":"","frontmatter":{"editLink":false},"headers":[],"relativePath":"changelog.md","filePath":"changelog.md","lastUpdated":1785486863000}'),o={name:"changelog.md"};function r(n,l,s,g,h,d){return a(),t("div",null,[...l[0]||(l[0]=[e('<h1 id="版本更新" tabindex="-1">版本更新 <a class="header-anchor" href="#版本更新" aria-label="Permalink to &quot;版本更新&quot;">​</a></h1><h2 id="文档站点-v2-4-1-2026-07-31" tabindex="-1">文档站点 v2.4.1（2026-07-31） <a class="header-anchor" href="#文档站点-v2-4-1-2026-07-31" aria-label="Permalink to &quot;文档站点 v2.4.1（2026-07-31）&quot;">​</a></h2><blockquote><p>对应项目代码版本 [v2.4.1]</p></blockquote><ul><li><strong>同步项目代码更新至 v2.4.1</strong></li><li>新增 v2.3.4 / v2.3.5 / v2.4.0 / v2.4.1 版本更新记录</li><li>更新系统管理文档：新增权限管理体系说明、三级权限结构详解、角色管理页面操作指南</li><li>更新 API 文档：新增权限接口、角色管理接口、网络拓扑接口、系统监控（CPU 使用率）接口</li><li>更新首页概览与 README 导航</li></ul><h2 id="文档站点-v1-0-0-2025-06-16" tabindex="-1">文档站点 v1.0.0（2025-06-16） <a class="header-anchor" href="#文档站点-v1-0-0-2025-06-16" aria-label="Permalink to &quot;文档站点 v1.0.0（2025-06-16）&quot;">​</a></h2><blockquote><p>对应项目代码版本 [v2.1.0]</p></blockquote><ul><li><strong>初始文档站点发布</strong></li><li>基于 VitePress 构建，部署于 GitHub Pages（<a href="https://gituib.github.io/idc_assest-docs/" target="_blank" rel="noreferrer">https://gituib.github.io/idc_assest-docs/</a>）</li><li>完整的使用指南：涵盖机房管理、设备管理、耗材管理、工单管理等所有功能模块的详细说明</li><li>开发手册：包含系统架构、前端架构、后端架构、数据模型等设计文档</li><li>部署运维指南：Docker 部署、手动部署、环境配置说明</li><li>API 文档：后端接口参考文档</li><li>版本更新记录与 FAQ 常见问题</li></ul><h2 id="项目代码" tabindex="-1">项目代码 <a class="header-anchor" href="#项目代码" aria-label="Permalink to &quot;项目代码&quot;">​</a></h2><h3 id="v2-4-1-2026-07-21" tabindex="-1">v2.4.1（2026-07-21） <a class="header-anchor" href="#v2-4-1-2026-07-21" aria-label="Permalink to &quot;v2.4.1（2026-07-21）&quot;">​</a></h3><h4 id="问题修复" tabindex="-1">问题修复 <a class="header-anchor" href="#问题修复" aria-label="Permalink to &quot;问题修复&quot;">​</a></h4><ul><li>前端组件新增多个组件 catch 分支的 message.error 提示（ServerBackplanePanel / BatchStatusModal / BatchWarrantyModal / DeviceFormModal / TopologyModal / AutoBackupSettings）</li><li>修复 CategoryManagement / ConsumableLogs / IdleDeviceManagement / InventoryManagement / TicketManagement 组件卸载后更新 state 的内存泄漏问题（新增 cancelledRef 模式）</li><li>移除 CableManagement / PortManagement / BackupManagement / IdleDeviceManagement 中的多余 console.log 调试输出</li><li>移除 CableManagement / PortManagement / TicketManagement 未使用的 import 引用</li><li>ConsumableManagement 修复 Tag 组件 key 从 index 改为 sn，消除 React key 警告</li><li>PortManagement 修复 clearInterval 在 importProgressInterval 上的变量作用域问题</li></ul><h3 id="v2-4-0-2026-07-21" tabindex="-1">v2.4.0（2026-07-21） <a class="header-anchor" href="#v2-4-0-2026-07-21" aria-label="Permalink to &quot;v2.4.0（2026-07-21）&quot;">​</a></h3><h4 id="新增功能——权限管理体系" tabindex="-1">新增功能——权限管理体系 <a class="header-anchor" href="#新增功能——权限管理体系" aria-label="Permalink to &quot;新增功能——权限管理体系&quot;">​</a></h4><ul><li>新增 requirePermission 中间件，支持细粒度按钮级权限控制</li><li>新增 init-permissions.js 种子脚本，预设三层权限结构（模块→菜单→按钮）</li><li>新增 RoleManagement 角色管理页面（前端页面 + 后端路由）</li><li>新增 permissions.js 路由，所有后端路由批量接入权限中间件</li><li>扩展 Permission 模型字段定义</li></ul><h4 id="新增功能——网络拓扑重构" tabindex="-1">新增功能——网络拓扑重构 <a class="header-anchor" href="#新增功能——网络拓扑重构" aria-label="Permalink to &quot;新增功能——网络拓扑重构&quot;">​</a></h4><ul><li>新增 CustomEdge 自定义边组件，支持线缆类型（以太网/光纤/铜缆）与状态着色</li><li>新增 GlassNodeShell / NodeShell / DeviceIcon 节点壳组件，提升设备节点视觉表现</li><li>新增 TopologyLayout 模型与 API，支持拓扑节点位置持久化</li><li>重构 TopologySidebar 侧边栏，布局与交互优化</li><li>优化 TopologyModal 与 TopologyControls 交互</li></ul><h4 id="功能改进" tabindex="-1">功能改进 <a class="header-anchor" href="#功能改进" aria-label="Permalink to &quot;功能改进&quot;">​</a></h4><ul><li>UserManagement 用户管理页面增强，集成角色分配与搜索筛选</li><li>Login 登录页面 UI 优化</li><li>3D 组件 DeviceModel / RackModel / Scene 渲染优化</li><li>前端路由 App.jsx 重构，优化页面组织结构</li><li>backend package.json 新增 init-database / init-permissions 脚本</li><li>hooks/useAuth 认证 hooks 优化</li><li>各路由统一接入鉴权中间件，修复未受保护的路由</li></ul><h3 id="v2-3-5-2026-07-21" tabindex="-1">v2.3.5（2026-07-21） <a class="header-anchor" href="#v2-3-5-2026-07-21" aria-label="Permalink to &quot;v2.3.5（2026-07-21）&quot;">​</a></h3><h4 id="功能改进-1" tabindex="-1">功能改进 <a class="header-anchor" href="#功能改进-1" aria-label="Permalink to &quot;功能改进&quot;">​</a></h4><ul><li>耗材统计页面 UI 全面重构：卡片数据驱动渲染、出入库对比改进度条+净流量徽章、类别分布改 SVG 环形图、新增快速筛选按钮</li><li>CI 升级 GitHub Actions 依赖版本（actions/checkout@v5、docker/login-action@v4、setup-buildx-action@v4、build-push-action@v6）</li></ul><h4 id="问题修复-1" tabindex="-1">问题修复 <a class="header-anchor" href="#问题修复-1" aria-label="Permalink to &quot;问题修复&quot;">​</a></h4><ul><li>systemSettings 修复 projectPath 路径错误（update.js 所在位置指向）</li><li>DeviceDetailDrawer 修复端口列表按名称数字段自然排序（支持 1/0/10 正确排序）</li></ul><h3 id="v2-3-4-2026-07-21" tabindex="-1">v2.3.4（2026-07-21） <a class="header-anchor" href="#v2-3-4-2026-07-21" aria-label="Permalink to &quot;v2.3.4（2026-07-21）&quot;">​</a></h3><h4 id="新增功能" tabindex="-1">新增功能 <a class="header-anchor" href="#新增功能" aria-label="Permalink to &quot;新增功能&quot;">​</a></h4><ul><li><strong>系统监控</strong>：新增基于 os.cpus().times 差值的 CPU 使用率采样器，跨平台准确获取（替代 os.loadavg）</li><li><strong>工单统计</strong>：新增工单趋势折线图组件（纯 SVG，无第三方依赖），支持悬浮查看每日设备详情</li><li><strong>工单统计</strong>：新增工单统计时间范围筛选预设（全部/7天/30天/90天/1年）</li><li><strong>工单管理</strong>：新增 cancelled（已取消）工单状态支持</li></ul><h4 id="功能改进-2" tabindex="-1">功能改进 <a class="header-anchor" href="#功能改进-2" aria-label="Permalink to &quot;功能改进&quot;">​</a></h4><ul><li>盘点模块后端 inventory.js 重构优化（+445/-209 行）</li><li>盘点任务执行前端 InventoryTaskExecution 页面优化</li></ul><h4 id="问题修复-2" tabindex="-1">问题修复 <a class="header-anchor" href="#问题修复-2" aria-label="Permalink to &quot;问题修复&quot;">​</a></h4><ul><li>系统信息修复 os.hostname() 引用 osUtils 冗余导入的问题</li><li>TicketStatistics 修复日期范围选择器支持清空（显示全部数据）</li></ul><h3 id="v2-3-3-2026-07-21" tabindex="-1">v2.3.3（2026-07-21） <a class="header-anchor" href="#v2-3-3-2026-07-21" aria-label="Permalink to &quot;v2.3.3（2026-07-21）&quot;">​</a></h3><ul><li><strong>在线更新优化</strong>：后端新增 isDocker 检测，区分 Docker/非Docker 环境的更新提示</li><li><strong>在线更新 UI 优化</strong>：加载态改为骨架屏脉搏动画，圆形图标增加背景容器，版本标签样式精简</li><li><strong>Docker 环境更新指引</strong>：在 Docker 运行时提示&quot;拉取最新镜像后重建容器&quot;，不再显示终端命令</li></ul><h3 id="v2-3-2-2026-07-21" tabindex="-1">v2.3.2（2026-07-21） <a class="header-anchor" href="#v2-3-2-2026-07-21" aria-label="Permalink to &quot;v2.3.2（2026-07-21）&quot;">​</a></h3><ul><li><strong>系统版本在线检查</strong>：新增系统版本在线检查功能，调用 GitHub API 获取最新 tag 并与当前版本比较</li><li><strong>在线更新界面</strong>：系统设置「关于系统」页新增「在线更新」卡片，支持一键检查新版本</li><li><strong>API 新增</strong>：<code>GET /api/system-settings/system/check-update</code> 版本检查接口（5 分钟缓存）</li></ul><h3 id="v2-3-1-2026-07-21" tabindex="-1">v2.3.1（2026-07-21） <a class="header-anchor" href="#v2-3-1-2026-07-21" aria-label="Permalink to &quot;v2.3.1（2026-07-21）&quot;">​</a></h3><ul><li><strong>备份恢复修复</strong>：修复 JSON 字段反序列化仅处理 Device.customFields，其他表 JSON 字段丢失的问题</li><li><strong>增量恢复修复</strong>：修复增量恢复中 JSON 字段未做反序列化的问题</li><li><strong>备份日志修复</strong>：修复日志模板字符串 <code>${var}</code> 在单引号中不生效的问题</li><li><strong>字段管理修复</strong>：修复 OptionsEditor 组件 <code>value</code> 传入 <code>undefined</code> 导致 <code>.map()</code> 报错</li><li><strong>备份配置完善</strong>：新增 Warehouse（仓库）、OperationLog（操作日志）的备份配置</li><li><strong>备份列表增强</strong>：过滤规则新增 <code>incremental_</code> 文件前缀支持</li></ul><h3 id="v2-3-0-2026-07-21" tabindex="-1">v2.3.0（2026-07-21） <a class="header-anchor" href="#v2-3-0-2026-07-21" aria-label="Permalink to &quot;v2.3.0（2026-07-21）&quot;">​</a></h3><ul><li><strong>邮箱验证与 SMTP 邮件服务</strong>：新增邮箱验证码登录与找回密码功能，支持 6 位验证码 5 分钟有效期</li><li><strong>SMTP 邮件配置管理</strong>：支持在系统设置中配置 SMTP 服务器，发送测试邮件与验证码邮件</li><li><strong>EmailVerifyBanner 组件</strong>：新增邮箱验证状态横幅，提醒未验证用户</li><li><strong>找回密码页面</strong>：新增基于邮箱验证码的密码重置流程</li><li><strong>邮件模板</strong>：新增测试邮件与验证码邮件的 EJS 模板</li><li><strong>账户设置增强</strong>：支持邮箱绑定与验证，优化交互体验</li><li><strong>SMTP 密码加密</strong>：新增 crypto 工具，SMTP 密码加密存储</li><li><strong>登录页面</strong>：新增「忘记密码」入口和验证码登录切换</li><li><strong>权限修复</strong>：修复 authStore 中 roles 未合并到 user 对象的权限判断问题</li><li><strong>UI 修复</strong>：修复邮件服务页面表单控件大小不一致、错误提示逻辑问题</li></ul><h3 id="v2-2-4-2026-07-17" tabindex="-1">v2.2.4（2026-07-17） <a class="header-anchor" href="#v2-2-4-2026-07-17" aria-label="Permalink to &quot;v2.2.4（2026-07-17）&quot;">​</a></h3><ul><li><strong>操作日志审计增强</strong>：新增操作日志操作类型（入库/出库/库存调整/上架/转入空闲/解锁/登录/登出等30+种类型），新增模块覆盖（空闲设备/端口管理/线缆管理/网卡管理/认证管理/系统设置/库房管理/备份管理）</li><li><strong>操作日志统计优化</strong>：统计数据兼容 MySQL 与 SQLite 的日期分组表达式</li><li><strong>备份操作日志审计</strong>：备份创建、恢复、上传、下载、删除、清理、配置更新等操作均记录详细审计日志</li><li><strong>认证操作日志审计</strong>：登录、登出、注册、解锁、密码修改等认证操作均记录详细审计日志</li><li><strong>3D 可视化增强</strong>：重构设备前面板布局与硬盘细节，提升设备辨识度</li><li><strong>端口列表排序</strong>：端口列表按名称数字段自然排序（如 eth0, eth1, ..., eth10）</li><li><strong>端口管理修复</strong>：修复交换机子页签误显示防火墙/路由器/存储设备的问题</li><li><strong>仪表盘修复</strong>：修复 NavigationGrid 响应式布局、QuickStats hover 动画、SystemInfo 伪造数据等5个 P0 级问题</li><li><strong>系统设置重构</strong>：外观设置（主题色）移除，命令区域改暗色终端风格 UI，复制兼容 execCommand 方案</li><li><strong>空闲设备优化</strong>：状态字段过滤 idle 选项</li></ul><h3 id="v2-2-3-2026-07-17" tabindex="-1">v2.2.3（2026-07-17） <a class="header-anchor" href="#v2-2-3-2026-07-17" aria-label="Permalink to &quot;v2.2.3（2026-07-17）&quot;">​</a></h3><ul><li><strong>3D 可视化优化</strong>：优化3D机柜设备颜色辨识度（服务器深石墨灰、交换机中灰偏蓝、防火墙深灰红调、存储深炭灰），增加设备上下银色边框条分隔相邻设备</li><li><strong>3D 结构增强</strong>：机柜内部两侧增加前安装轨，强化结构真实感与层次感</li><li><strong>3D 闪烁修复</strong>：修复4处 Z-fighting 深度冲突（侧板与立柱、前安装轨与前面板等），优化 OrbitControls 中键平移与全屏功能</li><li><strong>3D 页面布局重构</strong>：顶部 Header 改为浅色玻璃态适配 light theme，右侧 Rack Info 面板浅色玻璃态重构，新增底部 KPI 快捷栏</li><li><strong>3D 交互修复</strong>：修复 Header 按钮点击无响应、左键旋转失效等问题，规范化 Z-Index 层级体系</li><li><strong>仪表盘修复</strong>：修复 NavigationGrid 响应式布局、QuickStats hover 动画、SystemInfo 伪造数据、AnimatedCounter 动画重置、DeviceTrendChart 空数组异常等5个 P0 级问题</li><li><strong>端口管理修复</strong>：修复交换机子页签误显示防火墙/路由器/存储设备的问题</li><li><strong>端口管理增强</strong>：支持自定义设备类型进入端口管理，设备图标按类型区分背景色，新增「其他」Tab 展示自定义类型设备</li><li><strong>空闲设备优化</strong>：状态字段过滤 idle 选项</li></ul><h3 id="v2-2-2-2026-07-16" tabindex="-1">v2.2.2（2026-07-16） <a class="header-anchor" href="#v2-2-2-2026-07-16" aria-label="Permalink to &quot;v2.2.2（2026-07-16）&quot;">​</a></h3><ul><li><strong>分页配置扩展</strong>：前端分页可选条数扩展至 100/200/500/1000</li><li><strong>设备表单修复</strong>：修复设备表单字段重复渲染和残留值问题</li></ul><h3 id="v2-2-1-2026-07-11" tabindex="-1">v2.2.1（2026-07-11） <a class="header-anchor" href="#v2-2-1-2026-07-11" aria-label="Permalink to &quot;v2.2.1（2026-07-11）&quot;">​</a></h3><ul><li><strong>批量维保更新</strong>：新增批量更新设备维保信息功能，包含前后端完整实现</li><li><strong>端口选项集中管理</strong>：新增端口选项接口与集中管理 hook，统一维护端口/线缆类型数据</li><li><strong>端口/线缆类型扩展</strong>：扩展端口类型、线缆类型枚举值，支持更多硬件规格</li><li><strong>网卡编辑功能</strong>：新增网卡编辑功能，完善设备端口管理流程</li><li><strong>3D 机柜优化</strong>：优化3D机柜U位渲染逻辑，修复机柜使用率计算问题，重构3D材质与模型渲染</li><li><strong>3D 交互修复</strong>：修复3D可视化交互问题，优化背板渲染逻辑</li></ul><h3 id="v2-2-0-2026-07-03" tabindex="-1">v2.2.0（2026-07-03） <a class="header-anchor" href="#v2-2-0-2026-07-03" aria-label="Permalink to &quot;v2.2.0（2026-07-03）&quot;">​</a></h3><ul><li><strong>端口管理重构</strong>：重构端口管理页面，新增端口批量操作（批量编辑、批量清理）、分组预览功能，提升端口运维效率</li><li><strong>线缆管理优化</strong>：优化线缆管理流程，增强端口跳线引导体验，支持更直观的连线操作指引</li><li><strong>空闲设备管理功能</strong>：新增空闲设备列表与详情展示页面，支持按资产编号、设备名称、设备型号搜索筛选</li><li><strong>空闲设备字段优化</strong>：移除空闲设备表单中的资产状态和入库日期字段，优化数据录入体验</li><li><strong>用户管理列表优化</strong>：修复用户管理列表分页超出一页时系统设置 Tab 切换失效的问题</li><li><strong>盘点管理详情优化</strong>：修复盘点完成状态回显显示问题，优化部分页面字段展示</li><li><strong>耗材管理优化</strong>：修复耗材入库数量显示异常的问题</li><li><strong>无数据页面优化</strong>：优化空闲设备页面、库位页面、工单详情页的无数据展示提示</li><li><strong>系统稳定性提升</strong>：修复多处前端逻辑异常和状态管理问题</li></ul><h3 id="v2-1-1-2026-06-16" tabindex="-1">v2.1.1（2026-06-16） <a class="header-anchor" href="#v2-1-1-2026-06-16" aria-label="Permalink to &quot;v2.1.1（2026-06-16）&quot;">​</a></h3><ul><li><strong>端口管理优化</strong>：新增按设备分组的端口查询 API，修复端口过多时部分设备不显示的分页问题</li><li><strong>前端端口页面重构</strong>：改为设备维度分页，移除旧的端口级分页逻辑，统一端口名称自然排序</li></ul><h3 id="v2-1-0" tabindex="-1">v2.1.0 <a class="header-anchor" href="#v2-1-0" aria-label="Permalink to &quot;v2.1.0&quot;">​</a></h3><ul><li>优化系统设置页面</li><li>增强设备字段管理功能</li><li>改进3D可视化性能</li></ul><h3 id="v2-0-0" tabindex="-1">v2.0.0 <a class="header-anchor" href="#v2-0-0" aria-label="Permalink to &quot;v2.0.0&quot;">​</a></h3><ul><li><strong>重大更新：重构前端架构</strong>，采用 React + Vite 构建，提升开发效率和运行性能</li><li>引入 Three.js + @react-three/fiber，实现 3D 机柜可视化展示</li><li>新增工单管理系统：完整的工单流转、故障分类与优先级管理</li><li>新增耗材库存管理：入库出库、安全库存预警、SN 序列号追踪</li><li>新增资产盘点功能：盘点计划、暂存设备、盘盈处理</li><li>重构备份管理模块，支持更灵活的数据备份与恢复</li><li>增强 RBAC 权限控制，支持更细粒度的角色权限配置</li><li>升级 UI 组件库至 Ant Design 5</li></ul><h3 id="v1-0-0" tabindex="-1">v1.0.0 <a class="header-anchor" href="#v1-0-0" aria-label="Permalink to &quot;v1.0.0&quot;">​</a></h3><ul><li>初始版本发布</li><li>基本的设备 CRUD 功能</li><li>机房与机柜管理</li><li>简单的统计看板</li></ul>',56)])])}const v=i(o,[["render",r]]);export{u as __pageData,v as default};
